const $ = (s) => document.querySelector(s);
const esc = (v) => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// All sample business values are deliberately plain synthetic text.
function fixtures() {
  const rows = [
    {bank:'Northbank', number:'100020003001', country:'United Kingdom', type:'Bank', category:'Separate', balance:'42500', owner:'Alex Morgan'},
    {bank:'Cedar Bank', number:'100020003002', country:'Canada', type:'Bank', category:'Joint', balance:'18200', owner:'Taylor Morgan'},
    {bank:'Alpine Financial', number:'100020003003', country:'Switzerland', type:'Securities', category:'Separate', balance:'', owner:'Alex Morgan'},
    {bank:'Northbank', number:'100020003004', country:'United Kingdom', type:'Bank', category:'Separate', balance:'6800', owner:'Alex Morgan'}
  ];
  for (const row of rows) for (const value of Object.values(row)) {
    if (!/^[A-Za-z0-9 ]*$/.test(value)) throw new Error('Sample data must use only ASCII letters digits and spaces');
  }
  return rows;
}
const states = Object.fromEntries(['ledger','guided','review'].map(k => [k, {accounts:fixtures(), filer:{first:'Alex',last:'Morgan',year:'2025',country:'United Kingdom',city:'London',filerType:'Individual'}, section:'Accounts', selected:2, step:0, query:'', filter:'All accounts'}]));
let design = 'ledger';
const state = () => states[design];
const money = (value) => value === '' ? 'Not entered' : new Intl.NumberFormat('en-US', {style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(value));
const pending = () => state().accounts.filter(a=>!a.balance).length;
const filerName = () => esc(state().filer.first + ' ' + state().filer.last);
const mark = '<span class="brand-mark">✳</span>';
function badge(a) { return a.balance ? '<span class="badge good"><i></i>Complete</span>' : '<span class="badge warning"><i></i>Needs balance</span>'; }
function btn(text, action, primary=false, extra='') { return `<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${text}</button>`; }
function heading(kicker,title,sub,action='') { return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`; }
function nav() {return ['Overview','Filer details','Institutions','Owners','Accounts','Review'].map((name,i)=>`<button class="nav-item ${state().section===name?'active':''}" data-section="${name}"><span class="nav-icon">${['◫','○','▤','◉','▦','✓'][i]}</span>${name}${name==='Accounts'?`<span class="nav-count">${state().accounts.length}</span>`:name==='Review'&&pending()?`<span class="nav-alert">${pending()}</span>`:''}</button>`).join('');}
function accountRows() {
  const rows = state().accounts.map((a,i)=>({a,i})).filter(({a})=>(`${a.bank} ${a.number} ${a.country} ${a.owner}`.toLowerCase().includes(state().query.toLowerCase())) && (state().filter!=='Needs attention'||!a.balance));
  return rows.length ? rows.map(({a,i})=>`<tr><td><button class="account-link" data-edit="${i}"><span class="bank-avatar">${a.bank.slice(0,1)}</span><span><strong>${esc(a.bank)}</strong><small>${esc(a.country)}</small></span></button></td><td><span class="mono">${esc(a.number.slice(-4))}</span><small>${esc(a.type)}</small></td><td>${esc(a.category)}</td><td class="amount ${!a.balance?'missing':''}">${a.balance?money(a.balance):'Add balance'}</td><td>${badge(a)}</td><td><button class="icon-button" aria-label="Edit ${esc(a.bank)} account ${i+1}" data-edit="${i}">↗</button></td></tr>`).join('') : '<tr><td colspan="6" class="empty">No accounts match. Try a different search.</td></tr>';
}
function table() {return `<div class="table-scroll"><table><thead><tr><th>Institution</th><th>Account ending</th><th>Ownership</th><th class="amount">Maximum value · USD</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody id="account-rows">${accountRows()}</tbody></table></div>`;}
function filters() {return `<div class="table-toolbar"><div class="segmented">${['All accounts','Needs attention'].map(f=>`<button data-filter="${f}" class="${state().filter===f?'selected':''}">${f}${f==='Needs attention'?` <span>${pending()}</span>`:''}</button>`).join('')}</div><label class="search"><span>⌕</span><input id="search" aria-label="Search accounts" placeholder="Search accounts" value="${esc(state().query)}"></label></div>`;}
function ledgerAccounts() {return `${heading('YOUR 2025 REPORT','A little order. A lot of clarity.','All your accounts, with room to focus.',btn('+ Add account','add',true))}<div class="summary-strip"><div><span>Reporting year</span><strong>2025 <small>Individual filing</small></strong></div><div><span>Accounts in this report</span><strong>${String(state().accounts.length).padStart(2,'0')} <small>across ${new Set(state().accounts.map(a=>a.bank)).size} institutions</small></strong></div><div><span>Ready for review</span><strong>${state().accounts.length-pending()} <small>of ${state().accounts.length} accounts complete</small></strong></div></div><section class="ledger-table"><div class="section-title"><h2>Your accounts</h2><span class="quiet">Balances in US dollars</span></div>${filters()}${table()}<div class="table-footer"><span>${state().accounts.length} accounts · Separate and joint ownership</span><button class="text-button" data-action="add">Add another account <span>+</span></button></div></section><div class="ledger-bottom"><div class="next-note"><span class="round-icon">${pending()?'!':'✓'}</span><div><strong>${pending()?`${pending()} account needs a little attention`:'Everything is ready for a closer look'}</strong><p>${pending()?'Add the missing maximum balance to finish your account details.':'Your sample account details are complete.'}</p></div><button class="text-button" data-action="resolve">${pending()?'Finish details':'Review report'} →</button></div><p class="privacy">◇ Your files stay on your computer. Your draft stays yours.</p></div>`;}
function secondarySection() {
  const section = state().section;
  if(section==='Accounts') return ledgerAccounts();
  if(section==='Review') return reviewSummary();
  if(section==='Overview') return `${heading('REPORT OVERVIEW','Everything in its place.','Your ${esc(state().filer.year)} report at a glance.')}<div class="overview-grid">${[['Filer details',filerName(),'Ready to review'],['Institutions',`${new Set(state().accounts.map(a=>a.bank)).size} institutions`,'Shared across your accounts'],['Accounts',`${state().accounts.length} accounts`,`${pending()} needs attention`]].map(([s,t,d])=>`<button class="overview-card" data-section="${s}"><span class="eyebrow">${s}</span><h2>${t}</h2><p>${d}</p><span>Open →</span></button>`).join('')}</div><div class="callout"><h2>Pick up where you left off.</h2><p>Review your imported accounts, update the annual balances, then check the report.</p>${btn('Continue with accounts →','accounts',true)}</div>`;
  if(section==='Filer details') return `${heading('THE BASICS','Your report starts with you.','Review the sample filer details for this design study.')}<form id="filer-form" class="surface form-surface"><div class="form-grid">${field('First name','first',state().filer.first)}${field('Last name','last',state().filer.last)}${field('Reporting year','year',state().filer.year,'readonly')}${selectField('Filer type','filerType',state().filer.filerType,['Individual','Entity'])}${field('City','city',state().filer.city,'pattern="[A-Za-z0-9 ]*"')}${selectField('Country','country',state().filer.country,['United Kingdom','Canada','Switzerland'])}</div><div class="form-actions"><span class="quiet">Sample filer · UI demonstration</span><button class="button primary">Apply sample changes</button></div></form>`;
  const institutions=[...new Map(state().accounts.map(a=>[a.bank,a])).values()];
  return `${heading(section==='Owners'?'SHARED DETAILS':'INSTITUTION DIRECTORY',section==='Owners'?'The people behind the accounts.':'One institution. Every linked account.',section==='Owners'?'Owner records can be reused across joint accounts.':'Manage institution details once, wherever they appear.')}<div class="directory">${(section==='Owners'?[{bank:'Alex Morgan',country:'Filer'},{bank:'Taylor Morgan',country:'Joint owner'}]:institutions).map(a=>`<article class="directory-card"><span class="bank-avatar">${a.bank.slice(0,1)}</span><h2>${esc(a.bank)}</h2><p>${esc(a.country)}</p><div>${state().accounts.filter(x=>section==='Owners'?x.owner===a.bank:x.bank===a.bank).length} linked accounts</div><button class="text-button" data-related="${esc(a.bank)}">View linked accounts →</button></article>`).join('')}</div>`;
}
function ledger() {return `<div class="ledger shell"><aside class="sidebar"><div class="brand">${mark}<span>FBAR Hero</span></div><button class="report-picker" data-action="report"><span class="report-icon">25</span><span><strong>${esc(state().filer.year)} report</strong><small>${filerName()}</small></span><span>⌄</span></button><div class="nav-label">WORKSPACE</div><nav aria-label="Report sections">${nav()}</nav><div class="sidebar-bottom"><div class="local-indicator"><i></i> Local workspace</div><p>Synthetic data<br>Design prototype 01</p><button class="text-button" data-action="about">A note about this prototype ↗</button></div></aside><div class="workspace"><header class="workspace-header"><div>Personal report <span>/</span> ${state().section}</div><div class="header-actions"><span class="draft-state"><i></i> Sample draft</span>${btn('Review report ↗','review',true)}</div></header><div class="page-content">${secondarySection()}</div><footer class="workspace-footer"><span>FBAR Hero</span><span>Prepare with care. File with confidence.</span><span>2025 / Unsigned draft</span></footer></div></div>`;}
function field(label,name,value='',extra='') {return `<label class="field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,value,options) {return `<label class="field">${label}<select name="${name}">${options.map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('')}</select></label>`;}
function accountFields(a) {return `<div class="form-grid">${field('Institution name','bank',a.bank,'required pattern="[A-Za-z0-9 ]+"')}${field('Account number','number',a.number,'required pattern="[A-Za-z0-9 ]+"')}${selectField('Country','country',a.country,['United Kingdom','Canada','Switzerland'])}${selectField('Account type','type',a.type,['Bank','Securities','Other'])}${selectField('Ownership','category',a.category,['Separate','Joint','Signature authority'])}${field('Maximum value in USD','balance',a.balance,'inputmode="numeric" pattern="[0-9]+" placeholder="Enter amount" required')}</div><p class="field-note">Use plain sample data. This prototype stores edits only until you reload.</p>`;}
function guided() {
  const s=state(),a=s.accounts[s.selected],step=s.step;
  const titles=['A few details about you.','Give every account a home.','What was the highest balance?','One last look.'];
  const intros=['Start with the person this report belongs to.','Your imported accounts are here. Choose one to work on.','Let’s finish one account at a time.','Your report is taking shape. Check the details before the handoff.'];
  let content='';
  if(step===0) content=`<form id="guided-filer"><div class="form-grid">${field('First name','first',state().filer.first,'required pattern="[A-Za-z0-9 ]+"')}${field('Last name','last',state().filer.last,'required pattern="[A-Za-z0-9 ]+"')}${selectField('Country of residence','country',state().filer.country,['United Kingdom','Canada','Switzerland'])}${field('Reporting year','year',state().filer.year,'readonly')}</div><div class="gentle-note"><span>◇</span><p>Just the essentials to get started.<br><small>Additional filer fields would follow in the full application.</small></p></div><div class="guide-actions"><span>01 of 04</span><button class="button primary">Continue to accounts <span>→</span></button></div></form>`;
  if(step===1) content=`<div class="guided-account-list">${s.accounts.map((x,i)=>`<button class="guided-account ${i===s.selected?'chosen':''}" data-select="${i}"><span class="bank-avatar">${x.bank.slice(0,1)}</span><span><strong>${esc(x.bank)}</strong><small>${esc(x.country)} · ${x.number.slice(-4)}</small></span>${badge(x)}<span>→</span></button>`).join('')}</div><button class="text-button" data-action="add">+ Add an account</button><div class="guide-actions">${btn('← Back','back')}${btn('Continue to balances →','next',true)}</div>`;
  if(step===2) content=`<form id="guided-balance"><div class="selected-account"><span class="bank-avatar">${a.bank.slice(0,1)}</span><div><strong>${esc(a.bank)}</strong><small>${esc(a.type)} account · ${a.number.slice(-4)} · ${esc(a.country)}</small></div><button type="button" class="text-button" data-action="choose">Change</button></div><label class="balance-field">Maximum account value in 2025<span class="big-input"><span>$</span><input name="balance" aria-label="Maximum value in USD" value="${esc(a.balance)}" placeholder="0" inputmode="numeric" pattern="[0-9]+" required autofocus><span>USD</span></span></label><p class="quiet">Enter the maximum value for this account in US dollars.</p><details class="guide-help"><summary>Why do I need a maximum value?</summary><p>This field records the highest account value for the reporting year. The full application would include links to official instructions.</p></details><div class="guide-actions">${btn('← Back','back',false,'type="button"')}<button class="button primary">Save balance and continue →</button></div></form>`;
  if(step===3) content=`<div class="guide-complete"><span class="complete-symbol">${pending()?'◌':'✓'}</span><h2>${pending()?`${pending()} balance still to add`:'A good place to finish.'}</h2><p>${s.accounts.length} accounts · ${s.accounts.length-pending()} with balances</p></div><div class="review-mini">${s.accounts.map((x,i)=>`<button data-guided-edit="${i}"><span>${esc(x.bank)} <small>${x.number.slice(-4)}</small></span><strong class="${x.balance?'':'missing'}">${money(x.balance)} →</strong></button>`).join('')}</div><div class="guide-actions">${btn('← Back','back')}${btn(pending()?'Finish missing balances →':'See handoff →',pending()?'resolve':'handoff',true)}</div>`;
  return `<div class="guided"><header class="guided-header"><div class="brand">${mark}<span>FBAR Hero</span></div><span class="guided-year">Your ${esc(state().filer.year)} report</span><button class="text-button" data-action="about">How this works ↗</button></header><div class="guided-body"><aside class="journey"><div class="eyebrow">A CLEAR PATH TO DONE</div><h2>Less paperwork.<br>More peace of mind.</h2><p>One step, one account,<br>one thing at a time.</p><nav aria-label="Report steps">${['About you','Your accounts','Annual balances','Review and finish'].map((name,i)=>`<button data-step="${i}" class="journey-step ${i===step?'current':''}"><span>${i<step?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${name}</strong><small>${['The essentials','Bring everything together','Update this year','Ready for the next step'][i]}</small></div></button>`).join('')}</nav><div class="journey-footer"><span>◇</span><p>Made for a private moment.<br><small>Your files stay on your computer.</small></p></div></aside><section class="guided-stage"><div class="step-kicker">STEP ${String(step+1).padStart(2,'0')} <span>/ 04</span></div><h1>${titles[step]}</h1><p class="stage-intro">${intros[step]}</p><div class="guide-form">${content}</div><div class="guide-caption"><span>✳</span> Room to focus. Nothing extra.</div></section></div><footer class="guided-footer"><span>INTERACTION STUDY 02 · GUIDED</span><span>Synthetic data · Unsigned draft</span></footer></div>`;
}
function reviewSummary() {return `${heading('REVIEW YOUR REPORT',pending()?'A few finishing touches.':'Ready for your review.',`${state().accounts.length} sample accounts checked for missing balances.`)}<div class="surface review-summary"><div class="review-summary-top"><span class="complete-symbol">${pending()?'!':'✓'}</span><div><h2>${pending()?`${pending()} item to resolve`:'Sample balances complete'}</h2><p>This demo checks balances only. Full form validation belongs in the production app.</p></div></div>${state().accounts.map((a,i)=>`<button class="check-row" data-edit="${i}"><span>${a.balance?'✓':'!'} &nbsp; ${esc(a.bank)} <small>Account ${a.number.slice(-4)}</small></span><span>${a.balance?money(a.balance):'Add maximum value'} →</span></button>`).join('')}<div class="form-actions"><span class="quiet">Unsigned draft · Local workflow</span>${btn('Preview handoff →','handoff',true)}</div></div>`;}
function review() {
 const s=state(),a=s.accounts[s.selected];
 return `<div class="review-desk"><aside class="desk-rail"><div class="rail-mark">✳</div><button class="rail-button active" data-action="accounts" aria-label="Accounts workspace">▦</button><button class="rail-button" data-action="check" aria-label="Run sample checks">✓</button><button class="rail-button" data-action="handoff" aria-label="Preview handoff">↗</button><button class="rail-button rail-bottom" data-action="about" aria-label="About this prototype">?</button></aside><div class="desk-main"><header class="desk-header"><div><span class="desk-brand">FBAR Hero</span><span class="slash">/</span><span>Alex Morgan</span><span class="year-chip">2025</span></div><div class="header-actions"><span class="sample-chip">SAMPLE DRAFT</span>${btn('Review handoff ↗','handoff',true)}</div></header><div class="desk-title"><div><div class="eyebrow">REPORT WORKSPACE</div><h1>Every detail. In view.</h1></div><div class="desk-tabs"><button class="selected" data-action="accounts">Accounts <span>${s.accounts.length}</span></button><button data-action="check">Checks <span>${pending()}</span></button></div></div><div class="desk-layout"><section class="desk-accounts"><div class="desk-section-head"><h2>Account register</h2><button class="icon-button" data-action="add" aria-label="Add account">+</button></div><label class="search desk-search"><span>⌕</span><input id="desk-search" placeholder="Find an account" aria-label="Find an account" value="${esc(s.query)}"></label><div class="desk-account-list">${deskList()}</div><div class="desk-register-footer"><span>${s.accounts.length} accounts</span><span>${pending()} needs attention</span></div><div class="desk-note"><span>◇</span><p>Local by design<br><small>Sample edits stay in this tab.</small></p></div></section><section class="desk-inspector"><div class="inspector-top"><div class="eyebrow">ACCOUNT ${String(s.selected+1).padStart(2,'0')} / ${String(s.accounts.length).padStart(2,'0')}</div>${badge(a)}</div><h2>${esc(a.bank)}</h2><p class="quiet">${esc(a.country)} · Account ending ${a.number.slice(-4)}</p><form id="inspector-form"><div class="inspector-label">ACCOUNT DETAILS</div>${field('Institution name','bank',a.bank,'required pattern="[A-Za-z0-9 ]+"')}${field('Account number','number',a.number,'required pattern="[A-Za-z0-9 ]+"')}<div class="form-grid">${selectField('Type','type',a.type,['Bank','Securities','Other'])}${selectField('Ownership','category',a.category,['Separate','Joint','Signature authority'])}</div><div class="inspector-label">ANNUAL VALUE</div>${field('Maximum value in USD','balance',a.balance,'inputmode="numeric" required pattern="[0-9]+" placeholder="Enter amount"')}${!a.balance?'<p class="inline-warning">! Add this value to complete the account.</p>':'<p class="inline-success">✓ A maximum value has been entered.</p>'}<button class="button primary inspector-save">Apply changes <span>↗</span></button></form></section><aside class="desk-preview"><div class="preview-header"><span>REPORT OUTLINE</span><span class="live-tag"><i></i> Live sample</span></div><div class="paper"><div class="paper-top"><strong>FBAR</strong><span>2025</span></div><div class="paper-rule"></div><div class="paper-kicker">REPORT OF FOREIGN<br>BANK AND FINANCIAL ACCOUNTS</div><p class="paper-disclaimer">Design outline · Not an official form</p><div class="paper-section"><span>01</span> Filer information</div><div class="paper-pair"><span>Full name</span><strong>Alex Morgan</strong></div><div class="paper-pair"><span>Report year</span><strong>2025</strong></div><div class="paper-section"><span>02</span> Selected account</div><div class="paper-pair"><span>Institution</span><strong>${esc(a.bank)}</strong></div><div class="paper-pair"><span>Account number</span><strong>${esc(a.number)}</strong></div><div class="paper-pair"><span>Ownership</span><strong>${esc(a.category)}</strong></div><div class="paper-value ${a.balance?'':'unfilled'}"><span>Maximum value · USD</span><strong>${a.balance?money(a.balance):'Value required'}</strong></div><div class="paper-bottom">UNSIGNED DRAFT <span>${s.selected+1} / ${s.accounts.length}</span></div></div><div class="checks-panel"><div><h3>Quick checks</h3><span>${pending()} open</span></div><p><span class="check-dot">✓</span> ${s.accounts.length} sample accounts loaded</p><p><span class="${pending()?'warning-dot':'check-dot'}">${pending()?'!':'✓'}</span> ${pending()?`${pending()} maximum balance missing`:'All sample balances entered'}</p><button class="text-button" data-action="check">View check details →</button></div></aside></div><footer class="desk-footer"><span><i></i> SAMPLE WORKSPACE</span><span>03 / Review desk</span><span>Review · Validate · Sign in Adobe Reader</span></footer></div></div>`;
}
function deskList(){const rows=state().accounts.map((a,i)=>({a,i})).filter(({a})=>`${a.bank} ${a.number}`.toLowerCase().includes(state().query.toLowerCase()));return rows.length?rows.map(({a,i})=>`<button class="desk-account ${i===state().selected?'selected':''}" data-select="${i}"><span class="desk-account-top"><strong>${esc(a.bank)}</strong><span>${String(i+1).padStart(2,'0')}</span></span><span class="desk-account-meta">${a.number.slice(-4)} <span>${esc(a.category)}</span></span><span class="desk-account-value ${a.balance?'':'missing'}">${a.balance?money(a.balance):'Balance needed'}<span>${a.balance?'✓':'!'}</span></span></button>`).join(''):'<p class="empty">No matching accounts.</p>';}
function render() { document.body.dataset.design=design; document.querySelectorAll('[data-design]').forEach(a=>{if(a.dataset.design===design)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#app').innerHTML=design==='ledger'?ledger():design==='guided'?guided():review(); }
function switchDesign(){design=['ledger','guided','review'].includes(location.hash.slice(1))?location.hash.slice(1):'ledger';render();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function modal(title,body,wide=false){const d=$('#dialog');d.className=wide?'wide':'';d.innerHTML=`<div class="modal-heading"><div><div class="eyebrow">FBAR HERO / DESIGN STUDY</div><h2 id="dialog-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="Close dialog">×</button></div>${body}`;d.showModal();}
function editAccount(i,add=false){state().selected=i;const a=add?{bank:'',number:'',country:'United Kingdom',type:'Bank',category:'Separate',balance:''}:state().accounts[i];modal(add?'Add an account':'A closer look.',`<form id="account-form" data-add="${add}">${accountFields(a)}<div class="form-actions">${btn('Cancel','close',false,'type="button"')}<button class="button primary">${add?'Add sample account':'Apply changes'} →</button></div></form>`,true);}
function handoff(){modal('A thoughtful handoff.',`<p class="modal-intro">The full app prepares an unsigned PDF. You complete the filing outside FBAR Hero.</p><ol class="handoff-list"><li><span>01</span><div><strong>Check and download</strong><p>Resolve required fields and download your unsigned draft.</p></div></li><li><span>02</span><div><strong>Review in Adobe Reader</strong><p>Review, validate, sign and save the PDF.</p></div></li><li><span>03</span><div><strong>Submit through the filing service</strong><p>Upload your saved PDF yourself.</p></div></li></ol><div class="prototype-note">Design prototype only. PDF generation, import, signing and submission are not connected.</div><div class="form-actions">${btn('Back to prototype','close',true)}</div>`);}
document.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el)return;
 if(el.dataset.section){state().section=el.dataset.section;render();return;}
 if(el.dataset.related){state().section='Accounts';state().query=el.dataset.related;render();return;}
 if(el.dataset.filter){state().filter=el.dataset.filter;render();return;}
 if(el.dataset.edit!==undefined){editAccount(Number(el.dataset.edit));return;}
 if(el.dataset.select!==undefined){state().selected=Number(el.dataset.select);render();return;}
 if(el.dataset.guidedEdit!==undefined){state().selected=Number(el.dataset.guidedEdit);state().step=2;render();return;}
 if(el.dataset.step!==undefined){state().step=Number(el.dataset.step);render();return;}
 const action=el.dataset.action;
 if(action==='close')$('#dialog').close();
 if(action==='add')editAccount(state().selected,true);
 if(action==='review'){state().section='Review';render();}
 if(action==='accounts'){state().section='Accounts';state().query='';render();}
 if(action==='about')modal('Three ways to make room.',`<p class="modal-intro">Three different structures for the same FBAR workflow.</p><div class="about-designs"><p><strong>01 / Ledger</strong><br>A quiet, editorial workspace. Scan all accounts, then open the details you need.</p><p><strong>02 / Guided</strong><br>One task at a time. A deliberate sequence with generous space and clear next steps.</p><p><strong>03 / Review desk</strong><br>A compact working environment. Keep the register, selected account and report outline in view.</p></div><div class="prototype-note">All records are synthetic. Each design has independent state. Edits last until you reload. These studies demonstrate navigation, account edits and missing balance checks, not the full filing workflow.</div><div class="form-actions">${btn('Explore the designs','close',true)}</div>`);
 if(action==='report')modal('Your sample report.',`<p class="modal-intro">Alex Morgan · Reporting year 2025</p><p>This prototype focuses on the editing experience. Import and year rollover would connect to the existing application.</p><div class="form-actions">${btn('Back to workspace','close',true)}</div>`);
 if(action==='resolve'){const i=state().accounts.findIndex(a=>!a.balance);if(i<0){if(design==='guided')handoff();else{state().section='Review';render();}}else if(design==='guided'){state().selected=i;state().step=2;render();}else editAccount(i);}
 if(action==='next'){state().step=Math.min(3,state().step+1);render();}
 if(action==='back'){state().step=Math.max(0,state().step-1);render();}
 if(action==='choose'){state().step=1;render();}
 if(action==='handoff')handoff();
 if(action==='check')modal('Sample account checks',`${reviewSummary()}<div class="form-actions">${btn('Back to workspace','close',true)}</div>`,true);
});
document.addEventListener('input',e=>{if(e.target.id==='search'){state().query=e.target.value;$('#account-rows').innerHTML=accountRows();}if(e.target.id==='desk-search'){state().query=e.target.value;$('.desk-account-list').innerHTML=deskList();}});
document.addEventListener('submit',e=>{
 e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));
 if(['account-form','inspector-form'].includes(form.id)){
   if(Object.values(data).some(v=>!/^[A-Za-z0-9 ]*$/.test(v))){toast('Please use plain letters digits and spaces for sample data');return;}
   if(form.dataset.add==='true'){state().accounts.push({...data,owner:'Alex Morgan'});state().selected=state().accounts.length-1;}
   else Object.assign(state().accounts[state().selected],data);
   $('#dialog').close();render();toast('Sample account updated');
 }
 if(form.id==='guided-filer'){Object.assign(state().filer,data);state().step=1;render();}
 if(form.id==='guided-balance'){state().accounts[state().selected].balance=data.balance;state().step=3;render();toast('Sample balance updated');}
 if(form.id==='filer-form'){if(Object.values(data).some(v=>!/^[A-Za-z0-9 ]*$/.test(v))){toast('Please use plain letters digits and spaces for sample data');return;}Object.assign(state().filer,data);render();toast('Sample filer details updated');}
});
window.addEventListener('hashchange',switchDesign);
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open)$('#dialog').replaceChildren();});
switchDesign();
